    // ── Aplicar idioma ───────────────────────────────────────────────
    function apply(lang) {
        const translations = dict[lang] || dict[DEFAULT_LANG];
        const isRTL = false; // ninguno de los idiomas actuales es RTL

        mappings.forEach(([key, selector, prop]) => {
            const val = translations[key];
            if (!val) return;
            if (prop === 'pixel') {
                // Disparar evento custom para que index.js re-renderice la animación
                document.dispatchEvent(new CustomEvent('attomos:pixeltext', { detail: { text: val } }));
                return;
            }
            document.querySelectorAll(selector).forEach(el => {
                if (prop === 'text') el.textContent = val;
                else if (prop === 'html') el.innerHTML = val;
                else el.setAttribute(prop, val);
            });
        });

        // Traducir data-translate-title (atributo title de botones/links)
        document.querySelectorAll('[data-translate-title]').forEach(el => {
            const key = el.getAttribute('data-translate-title');
            if (translations[key]) el.setAttribute('title', translations[key]);
        });

        // Traducir data-translate-placeholder (inputs)
        document.querySelectorAll('[data-translate-placeholder]').forEach(el => {
            const key = el.getAttribute('data-translate-placeholder');
            if (translations[key]) el.setAttribute('placeholder', translations[key]);
        });

        // Traducir botones de plan generados por Go templates
        document.querySelectorAll('.plan-button.primary').forEach(btn => {
            btn.textContent = translations['plan_btn_primary'] || btn.textContent;
        });
        document.querySelectorAll('.plan-button.secondary').forEach(btn => {
            btn.textContent = translations['plan_btn_secondary'] || btn.textContent;
        });
        document.querySelectorAll('.price-period').forEach(el => {
            el.textContent = translations['price_period'] || el.textContent;
        });

        // Guardar preferencia
        setLang(lang);

        // Marcar activo en el botón del navbar
        document.querySelectorAll('.lang-option').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.lang === lang);
        });

        // Actualizar label del botón trigger (SVG flag + código)
        const meta = LANG_META[lang];
        if (meta) {
            const labelHtml = (FLAG_SVG[lang] || '') + ' ' + meta.code;
            ['langTriggerLabel', 'langTriggerLabelMobile'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.innerHTML = labelHtml;
            });
        }

        console.log(`🌐 Idioma aplicado: ${lang}`);
    }

    // ── Renderizar opciones del dropdown con SVG flags ───────────────
    function renderLangOptions() {
        document.querySelectorAll('.lang-option[data-lang]').forEach(btn => {
            const lang = btn.dataset.lang;
            const meta = LANG_META[lang];
            if (!meta) return;
            const flagSvg = FLAG_SVG[lang] || '';
            btn.innerHTML = flagSvg + ' ' + meta.label;
        });
    }

    // ── Inicializar con idioma guardado o predeterminado ─────────────
    function init() {
        renderLangOptions();
        const saved = getLang();
        apply(saved);
    }

    // ── SVG Flags — compatibles con Windows, estilo LineIcons ────────
